//! Current workaround for a nonconstant pair meaning: an independent circuit specification.
use std::quantum::init0;
use std::quantum::x;
use std::quantum::z;
use std::quantum::join;
use std::quantum::split;
use std::routines::measure_z2;

basis fn marked((a,b): (Bit,Bit)) -> Bit { a and b }
unitary fn oracle(q: Q<(Bit,Bit)>) -> Q<(Bit,Bit)> {
    with_computed(q,marked) { |flag| z(flag) }
}
unitary fn identity(q: Q<Bit>) -> Q<Bit> { q }
unitary fn specified(q: Q<(Bit,Bit)>) -> Q<(Bit,Bit)> {
    let (a,b) = split(q);
    let (a,b) = qif(a,b) { 0 => identity, 1 => z };
    join(a,b)
}
observe fn main() -> (CBit,CBit) {
    measure_z2(apply_contract(oracle,specified,join(x(init0()),x(init0()))))
}

//! Experimental fixed-width arithmetic; leftmost bits have the lowest weight.
//!
//! All definitions are ordinary checked .qli and return every input wire.
//! Full-space contracts, including overflow and value 15, are documented in
//! Contract identifiers: A001-A003.
//! These are fixed finite routines, not generalized integer arithmetic.
use std::quantum::x;
use std::quantum::cnot;
use std::quantum::toffoli;
use std::quantum::split;
use std::quantum::join;

/// Map |y> to |(y + 1) mod 4> with amplitude +1 for every two-bit input.
/// The first bit has weight 1 and the second weight 2; overflow wraps.
/// Consume and return both owners with no auxiliary or measurement.
pub unitary fn increment2(q: Q<(Bit, Bit)>) -> Q<(Bit, Bit)> {
    let (low, high) = split(q);
    let (low, high) = cnot(low, high);
    join(x(low), high)
}

/// Map |x,y> to |x,(y + x) mod 4> with amplitude +1 for all x,y in 0..4.
/// The first pair stores x and the second y, each least-significant bit first.
/// Return all four owners in those positions; no auxiliary or input promise.
pub unitary fn add2(q: Q<((Bit, Bit), (Bit, Bit))>) -> Q<((Bit, Bit), (Bit, Bit))> {
    let (a, b) = split(q);
    let (a0, a1) = split(a);
    let (b0, b1) = split(b);
    // Carry must use the original low bits, before b0 is overwritten.
    let ((a0, b0), b1) = toffoli(a0, b0, b1);
    let (a1, b1) = cnot(a1, b1);
    let (a0, b0) = cnot(a0, b0);
    join(join(a0, a1), join(b0, b1))
}

/// Map |y> to |2*y mod 15> for 0 <= y < 15, and leave |15> fixed.
/// Every basis image has amplitude +1; no residue-range promise is needed.
/// Input bits (a,b,c,d) have weights (1,2,4,8); return owners as (d,a,b,c).
/// This whole-space permutation uses no auxiliary and performs no measurement.
pub unitary fn mul2_mod15(q: Q<((Bit, Bit), (Bit, Bit))>) -> Q<((Bit, Bit), (Bit, Bit))> {
    let (ab, cd) = split(q);
    let (a, b) = split(ab);
    let (c, d) = split(cd);
    // Rotation implements 2*y mod 15 for y<15, and fixes 15.
    join(join(d, a), join(b, c))
}

//! Total finite basis functions, implemented as ordinary checked source.
//!
//! These functions take basis labels, not quantum owners or measurement results.
//! Importing them grants no quantum primitive or verification privilege.
//! Contracts and finite regression status: Contract identifiers: B001-B002.

/// Return x xor y for all four pairs of Bit inputs.
/// This two-argument map is total but not injective on the product domain.
/// A coherent lift must check injectivity of its complete enclosing map.
pub basis fn xor2(x: Bit, y: Bit) -> Bit { x xor y }

/// Return x and y for all four pairs of Bit inputs.
/// This total, noninjective predicate can describe reversible XOR computation
/// into an auxiliary; calling it does not measure a quantum register.
pub basis fn and2(x: Bit, y: Bit) -> Bit { x and y }

//! Finite algorithm building blocks; ordinary checked Qleisli definitions.
//!
//! Separate owners may remain entangled; no routine assumes a product state.
//! Contracts, including reflection phase and observation instruments, are in
//! Contract identifiers: R001-R005.
use std::quantum::init0;
use std::quantum::h;
use std::quantum::z;
use std::quantum::cnot;
use std::quantum::split;
use std::quantum::join;
use std::observe::measure_z;

/// Apply H tensor H to a two-bit register, preserving both owners and order.
/// This unitary has no input-state promise and uses no auxiliary.
pub unitary fn hadamard2(q: Q<(Bit, Bit)>) -> Q<(Bit, Bit)> {
    let (a, b) = split(q);
    join(h(a), h(b))
}

/// Return 0 exactly on (0,0), and 1 on every other pair of basis labels.
/// Computing this predicate and applying Z to its auxiliary gives phase +1
/// on 00 and -1 elsewhere: 2|00><00| - I, including its sign.
basis fn nonzero2((a, b): (Bit, Bit)) -> Bit { not (not a and not b) }

/// Apply the phase-fixed reflection 2|s><s| - I, with |s> = (H tensor H)|00>.
/// Consume and return the two data owners with no input-state promise.
/// The protected computed scope checks zero return of its temporary auxiliary;
/// the name of this routine and this documentation do not grant that evidence.
pub unitary fn reflect_uniform2(q: Q<(Bit, Bit)>) -> Q<(Bit, Bit)> {
    let q = hadamard2(q);
    let q = with_computed(q, nonzero2) { |ancilla| z(ancilla) };
    hadamard2(q)
}

/// Measure the X eigenvalue (-1)^b and return the classical result b.
/// Consume the target owner; interpret the measurement with all references.
pub observe fn measure_x(q: Q<Bit>) -> CBit {
    measure_z(h(q))
}

/// Measure both bits in Z and consume both quantum owners.
/// Return (left result, right result), corresponding to register weights 1,2.
pub observe fn measure_z2(q: Q<(Bit, Bit)>) -> (CBit, CBit) {
    let (a, b) = split(q);
    (measure_z(a), measure_z(b))
}

/// Measure Z(a) Z(b), consuming the internal meter and returning both data owners.
/// For result s, the data projector is (I + (-1)^s Z tensor Z)/2.
/// Preserve coherence within each parity subspace and return ((a,b),s).
/// Inputs must be distinct owners, but may be entangled with each other or a reference.
pub observe fn parity_zz(a: Q<Bit>, b: Q<Bit>) -> ((Q<Bit>, Q<Bit>), CBit) {
    let meter = init0();
    let (a, meter) = cnot(a, meter);
    let (b, meter) = cnot(b, meter);
    ((a, b), measure_z(meter))
}

//! Fixed two- and three-bit quantum Fourier transforms with positive phase.
//!
//! Ordinary checked .qli definitions; no general-size or approximate QFT API.
//! Basis labels are little-endian and each circuit includes output-bit reversal.
//! Contracts and finite regression status: Contract identifiers: F001-F002.
use std::quantum::h;
use std::quantum::t;
use std::quantum::s;
use std::quantum::id;
use std::quantum::split;
use std::quantum::join;

/// Apply F4: |x> maps to sum_y exp(2*pi*i*x*y/4)|y>/2 for every input.
/// The leftmost bit has weight 1; output reversal is part of the exact unitary.
/// Consume and return both owners without measurement or auxiliary allocation.
pub unitary fn qft2(q: Q<(Bit, Bit)>) -> Q<(Bit, Bit)> {
    let (a, b) = split(q);
    let b = h(b);
    let (a, b) = qif(a, b) { 0 => id, 1 => s };
    let a = h(a);
    join(b, a)
}

/// Apply F8: |x> maps to sum_y exp(2*pi*i*x*y/8)|y>/sqrt(8) for every input.
/// For input ((a,b),c), x = a + 2*b + 4*c; output reversal is included.
/// Consume and return all three owners with no measurement or auxiliary.
pub unitary fn qft3(q: Q<((Bit, Bit), Bit)>) -> Q<((Bit, Bit), Bit)> {
    let (ab, c) = split(q);
    let (a, b) = split(ab);
    let c = h(c);
    let (b, c) = qif(b, c) { 0 => id, 1 => s };
    let (a, c) = qif(a, c) { 0 => id, 1 => t };
    let b = h(b);
    let (a, b) = qif(a, b) { 0 => id, 1 => s };
    let a = h(a);
    join(join(c, b), a)
}
